 public function test_pitch_needs_do_not_assume_power_and_revoked_upstream_invalidates_supply(): void {
  $p=$this->plan();$d=$this->relay($p);$stand=$d->standPartner->stand;$main=SiteInfrastructure::create(['event_project_id'=>$p->event_project_id,'name'=>'LS 4x16','kind'=>'main_supply','conductor_count'=>4,'section_mm2'=>16]);$this->assertNull($main->amp_limit);$this->invalid(fn()=>$main->update(['status'=>'approved']));$main->refresh();$main->update(['amp_limit'=>20,'voltage_v'=>230,'phases'=>'single','earth_verified'=>true,'review_evidence'=>'Professional checks']);$main->update(['status'=>'approved']);
  $branch=SiteInfrastructure::create(['event_project_id'=>$p->event_project_id,'name'=>'Branch','kind'=>'distribution','source_id'=>$main->id,'amp_limit'=>4,'voltage_v'=>230,'phases'=>'single','earth_verified'=>true,'review_evidence'=>'Professional checks','status'=>'approved']);$need=StandRequirement::create(['stand_id'=>$stand->id,'name'=>'Light','kind'=>'electricity','justification'=>'Evening light','power_w'=>20,'line_length_m'=>15,'source_id'=>$branch->id,'provided_by'=>'qapas','status'=>'approved','review_evidence'=>'Checked']);$this->assertTrue($need->valid());$this->invalid(fn()=>StandRequirement::create(['stand_id'=>$stand->id,'name'=>'Water','kind'=>'water','justification'=>'Cleaning','source_id'=>$branch->id,'provided_by'=>'qapas','status'=>'approved','review_evidence'=>'Wrong kind']));$main->update(['cable_marking'=>'Changed cable']);$this->assertFalse($need->valid());$other=$this->plan('other');$foreign=SiteInfrastructure::create(['event_project_id'=>$other->event_project_id,'name'=>'Foreign','kind'=>'generator']);$this->invalid(fn()=>$need->update(['source_id'=>$foreign->id]));$this->invalid(fn()=>$main->update(['source_id'=>$branch->id]));
 }
 public function test_new_admin_forms_render_including_dynamic_relations_and_cash_settlement(): void {
  $this->seed();$this->admin();foreach(['OutreachVisit','SiteInfrastructure','PresalePlan','Distributor','EventTicket','TicketSettlement','TicketMessage'] as $name){$class='App\\Filament\\Resources\\'.$name.'Resource';$this->get($class::getUrl())->assertOk();if(in_array($name,['OutreachVisit','SiteInfrastructure','PresalePlan','Distributor','TicketSettlement'])){$page=$class.'\Pages\ManageRecords';\Livewire\Livewire::test($page)->mountAction('create')->assertHasNoActionErrors();}}
