 public function test_late_received_candidate_cash_is_recorded_for_review_not_validated_after_vote_deadline(): void {
  $p=$this->plan();$d=$this->relay($p);$campaign=RegistrationCampaign::create(['event_project_id'=>$p->event_project_id,'name'=>'Experts','terms_version'=>'candidate-v1','terms_fr'=>'Terms','terms_pt'=>'Condições','refund_policy_fr'=>'Refund','refund_policy_pt'=>'Reembolso','vat_basis_points'=>0,'billing_procedure'=>'Invoices','validation_evidence'=>'Review','closes_at'=>now()->addDays(10),'is_open'=>true]);
  $t=$this->ticket($p,$d,['candidate'=>true,'candidate_terms_version'=>'candidate-v1','expert_roles'=>['cook']]);$this->travel(11)->days();app(Ticketing::class)->settle($d,[$t->id],900,'LATE','Funds arrived after cutoff',now());$this->assertSame('review',$t->fresh()->status);$this->assertFalse($t->fresh()->candidate->isPaid());$this->assertDatabaseCount('ticket_messages',0);$this->assertSame(1000,$p->report()['review_received_cents']);app(Ticketing::class)->refundCash($t,'Full refund paid; commission returned',100);$this->assertSame('refunded',$t->fresh()->status);
 }
 public function test_sms_acceptance_does_not_claim_delivery_until_provider_confirms(): void {
  $p=$this->plan();$d=$this->relay($p);$t=$this->ticket($p,$d);app(Ticketing::class)->settle($d,[$t->id],900,'SMS2','Proof',now());config(['registration.live'=>true,'presales.sms_enabled'=>true,'presales.twilio_sid'=>'ACfixture','presales.twilio_token'=>'secret','presales.twilio_from'=>'+351211234567']);$t->update(['is_live'=>true]);$sid='SM'.str_repeat('1',32);Http::preventStrayRequests();Http::fake(['api.twilio.com/*'=>Http::sequence()->push(['sid'=>$sid,'status'=>'queued'])->push(['sid'=>$sid,'status'=>'sent'])->push(['sid'=>$sid,'status'=>'delivered'])]);
  $this->assertSame(1,app(TicketSms::class)->dispatch());$this->assertSame('accepted',$t->messages()->first()->status);$this->assertNull($t->messages()->first()->delivered_at);app(TicketSms::class)->dispatch();$this->assertSame('delivered',$t->messages()->first()->status);$this->assertNotNull($t->messages()->first()->delivered_at);Http::assertSentCount(3);
 }

